INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1323522', 'League War', 'The League War was the second civil war of Costa Rica, as a member state of the Federal Republic of Central America. It passed between September and October 1835 in the Central Valley of Costa Rica.', 1835, 10, NULL, 1835, 10, NULL, 'month', 'October 1835', 30, 'https://en.wikipedia.org/wiki/League_War'),
  ('Q66005195', '1870 Costa Rican coup d''état', 'The coup d''état of April 27, 1870 in Costa Rica was a coup implemented by the military leadership led by Tomás Guardia Gutiérrez and it established, to a large extent, the inauguration of the Liberal State. It also enacted the Costa Rican Constitution of 1871, the longest in Costa Rican history as it remained in force until 1948.', 1870, 4, 27, NULL, NULL, NULL, 'day', '27 April 1870', 26, 'https://en.wikipedia.org/wiki/1870_Costa_Rican_coup_d''%C3%A9tat'),
  ('Q5918797', 'Barrios'' War of Reunification', 'Barrios'' War of Reunification, also known as Barrios'' great attempt (Spanish: intentona de Barrios), was a war initiated by Guatemalan President Justo Rufino Barrios in 1885 with the goal of reunifying Central America. Of the five Central American countries, only Honduras supported Barrios'' reunification effort; Costa Rica, El Salvador, and Nicaragua opposed it, as did Mexico.', 1885, 2, 28, 1885, 4, 14, 'day', '28 February 1885 – 14 April 1885', 26, 'https://en.wikipedia.org/wiki/Barrios''_War_of_Reunification'),
  ('Q21002917', '1917 Costa Rican coup d''état', 'The 1917 Costa Rican coup d''état of 27 January 1917 was a rupture of the constitutional order in the Republic of Costa Rica, where the constitutional President Alfredo González Flores, was overthrown by his Minister of War and Navy Federico "Pelico" Tinoco and his brother and army commander José Joaquín Tinoco. The coup had the support of the Costa Rican oligarchy —mainly the bankers and coffee growers— affected by González''s tax reform, particularly a greater tax burden for the big capital.', 1917, 1, 27, NULL, NULL, NULL, 'day', '27 January 1917', 37, 'https://en.wikipedia.org/wiki/1917_Costa_Rican_coup_d''%C3%A9tat'),
  ('Q5887735', 'Coto War', 'The Coto War (Spanish: Guerra de Coto) was a conflict between Panama and Costa Rica fought between 21 February and 5 March 1921. The casus belli occurred when a Costa Rican expeditionary force led by Colonel Héctor Zúñiga Mora occupied the town of Pueblo Nuevo de Coto, a hamlet on the banks of the Coto River.', 1921, NULL, NULL, 1921, 3, 5, 'year', '1921', 41, 'https://en.wikipedia.org/wiki/Coto_War'),
  ('Q3434218', 'Costa Rican Civil War', 'The Costa Rican Civil War, domestically referred to as the War of ''48 or the Revolution of ''48 (Spanish: Guerra del 48; Revolución del 48), took place from 12 March to 24 April 1948. The conflict followed the presidential elections of 8 February 1948, in which opposition candidate Otilio Ulate defeated the ruling party''s Rafael Ángel Calderón Guardia.', 1948, 3, 12, 1948, 4, 24, 'day', '12 March 1948 – 24 April 1948', 57, 'https://en.wikipedia.org/wiki/Costa_Rican_Civil_War'),
  ('Q4586935', '1991 Limon earthquake', 'The 1991 Costa Rica earthquake, also known as the Limon earthquake or Bocas del Toro earthquake, occurred at 3:57 pm local time (21:56:51 UTC) on April 22. The epicenter of the 7.7 Mw earthquake was in Pandora, Valle La Estrella, in the Caribbean region of Limon, Costa Rica, 225 kilometres (140 mi) southeast of San José.', 1991, 4, 22, NULL, NULL, NULL, 'day', '22 April 1991', 34, 'https://en.wikipedia.org/wiki/1991_Limon_earthquake'),
  ('Q3299278', '2009 Costa Rica earthquake', 'The 2009 Cinchona earthquake occurred at 1:21:35 pm local time on January 8 with an Mwc magnitude of 6.1 and a maximum Mercalli intensity of IX ( Violent). The shock took place in northern Costa Rica, 30 kilometres (19 mi) north-northwest of San José and was felt throughout Costa Rica and in southern central Nicaragua.', 2009, 1, 8, NULL, NULL, NULL, 'day', '8 January 2009', 43, 'https://en.wikipedia.org/wiki/2009_Cinchona_earthquake'),
  ('Q7388664', 'SANSA Flight 32', 'SANSA Flight 32, a CASA C-212 Aviocar on its way to Palmar Sur Airport crashed into the Cerro Cedral, a mountain in Costa Rica after takeoff from Juan Santamaría International Airport in San Jose on January 15, 1990. All 20 passengers and 3 crew on board died in the crash.', 2011, 1, 15, NULL, NULL, NULL, 'day', '15 January 2011', 45, 'https://en.wikipedia.org/wiki/SANSA_Flight_32'),
  ('Q2702014', '2012 Costa Rica earthquake', 'The 2012 Costa Rica earthquake occurred at 08:42 local time (14:42 UTC) on September 5. The epicenter of the 7.6 Mw earthquake was in the Nicoya Peninsula, 11 kilometers east-southeast of Nicoya.', 2012, 9, 5, NULL, NULL, NULL, 'day', '5 September 2012', 41, 'https://en.wikipedia.org/wiki/2012_Costa_Rica_earthquake'),
  ('Q43084692', '2017 Costa Rica earthquake', 'On 12 November 2017 an earthquake with a moment magnitude of 6.5 occurred near Jacó, Costa Rica. It was also felt in parts of Nicaragua and Panama and was followed by more than 20 aftershocks.', 2017, 11, 12, NULL, NULL, NULL, 'day', '12 November 2017', 34, 'https://en.wikipedia.org/wiki/2017_Costa_Rica_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q111524038', 'DHL Aero Expreso Flight 7216', 'DHL de Guatemala Flight 7216 was an international cargo flight between Costa Rica''s Juan Santamaría International Airport and Guatemala City''s La Aurora International Airport. On 7 April 2022 (2022-04-07), the Boeing 757 suffered a hydraulic failure, and crashed on landing at the Costa Rican airport.', 2022, 4, 7, NULL, NULL, NULL, 'day', '7 April 2022', 50, 'https://en.wikipedia.org/wiki/DHL_de_Guatemala_Flight_7216');
